-- 1. Close the broad defaults
REVOKE ALL ON DATABASE appdb FROM PUBLIC;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- 2. Group roles hold privileges and cannot log in
CREATE ROLE app_rw NOLOGIN;
CREATE ROLE app_ro NOLOGIN;

-- 3. A dedicated schema, owned by the migration role
CREATE ROLE app_migrator LOGIN PASSWORD '<placeholder-from-secrets-manager>';
CREATE SCHEMA app AUTHORIZATION app_migrator;

GRANT CONNECT ON DATABASE appdb TO app_rw, app_ro;
GRANT USAGE ON SCHEMA app TO app_rw, app_ro;

-- 4. Future tables created by the migrator get the right grants automatically
ALTER DEFAULT PRIVILEGES FOR ROLE app_migrator IN SCHEMA app
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_rw;
ALTER DEFAULT PRIVILEGES FOR ROLE app_migrator IN SCHEMA app
  GRANT SELECT ON TABLES TO app_ro;
ALTER DEFAULT PRIVILEGES FOR ROLE app_migrator IN SCHEMA app
  GRANT USAGE, SELECT ON SEQUENCES TO app_rw;

-- 5. Login roles are members of the groups
CREATE ROLE web_app LOGIN PASSWORD '<placeholder>' CONNECTION LIMIT 50 IN ROLE app_rw;
CREATE ROLE report_svc LOGIN PASSWORD '<placeholder>' CONNECTION LIMIT 5 IN ROLE app_ro;

CREATE ROLE 'app_rw', 'app_ro';
GRANT SELECT, INSERT, UPDATE, DELETE ON appdb.* TO 'app_rw';
GRANT SELECT ON appdb.* TO 'app_ro';

CREATE USER 'web_app'@'10.20.1.%' IDENTIFIED BY '<placeholder>'
  REQUIRE SSL WITH MAX_USER_CONNECTIONS 50;
GRANT 'app_rw' TO 'web_app'@'10.20.1.%';
SET DEFAULT ROLE 'app_rw' TO 'web_app'@'10.20.1.%';

-- Remove anonymous and remote-root exposure
DROP USER IF EXISTS ''@'localhost';
SELECT user, host FROM mysql.user WHERE user = 'root';

